    SELECT *, ROW_NUMBER() OVER (
        PARTITION BY customer_id ORDER BY order_date
    ) AS rn
    FROM Delivery
)
SELECT ROUND(100.0 * AVG(order_date = customer_pref_delivery_date), 2) AS immediate_percentage
FROM first_orders
WHERE rn = 1;

